@sig trait BeltQualificationOwner_Api {
  def id: Art.BridgeId
  def beltObservation_Id : Art.PortId
  def beltAssessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var beltAssessment: EIT_Acquisition_Session_Coordinator.BeltAssessment = $

  def put_beltAssessment(value : EIT_Acquisition_Session_Coordinator.BeltAssessment) : Unit = {
    Contract(
      Modifies(beltAssessment),
      Ensures(
        beltAssessment == value
      )
    )
    Spec {
      beltAssessment = value
    }

    Art.putValue(beltAssessment_Id, EIT_Acquisition_Session_Coordinator.BeltAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class BeltQualificationOwner_Initialization_Api (
  val id: Art.BridgeId,
  val beltObservation_Id : Art.PortId,
  val beltAssessment_Id : Art.PortId) extends BeltQualificationOwner_Api

@datatype class BeltQualificationOwner_Operational_Api (
