  @spec var beltObservation: EIT_Acquisition_Session_Coordinator.BeltObservation.Type = $

  def get_beltObservation() : Option[EIT_Acquisition_Session_Coordinator.BeltObservation.Type] = {
    Contract(
      Ensures(
